#include "../src/effects.h"
#include <cstdio>
#include <functional>
#include <limits>
#include <stdexcept>
#include <string>
static void Check(bool b,const char* why){if(!b)throw std::runtime_error(why);}
static World Desktop(){World w;w.virt={-1920,-200,1920,1080};w.monitors.push_back({{0,0,1920,1080},{0,0,1920,1040},1040,1});return w;}
static void Density(int value){snowfx::Cfg().intensity=rainfx::Cfg().intensity=leavesfx::Cfg().intensity=halloweenfx::Cfg().intensity=value;}
static size_t Actors(const Effects&e,int id){switch(id){case EFFECT_SNOW:return e.snow.flakes.size();case EFFECT_RAIN:return e.rain.drops.size();case EFFECT_LEAVES:return e.leaves.airborne.size();default:return e.halloween.airborne.size()+e.halloween.webs.size();}}
static void Step(Effects&e,World&w,int frames){for(int i=0;i<frames;++i)e.Update(1.f/60,w,{0,0},false);}
static void SetField(int effect,const wchar_t* key,int value){for(auto f:ProfileFields(effect))if(std::wstring(f.key)==key){if(f.i)*f.i=value;else *f.b=value!=0;return;}throw std::runtime_error("field absent");}
static int Field(int effect,const wchar_t* key){for(auto f:ProfileFields(effect))if(std::wstring(f.key)==key)return f.i?*f.i:*f.b;throw std::runtime_error("field absent");}
static halloweenfx::WebSpider Spider(){halloweenfx::WebSpider p;p.anchorX=p.x=500;p.y=200;p.targetY=200;p.size=16;p.scale=1;p.monitor={0,0,1920,1080};p.state=halloweenfx::SPIDER_HANGING;p.wait=20;return p;}
static void Finite(const Effects&e){
 Check(e.snow.flakes.size()<=7000&&e.rain.drops.size()<=7000&&e.rain.splashes.size()<=1200&&e.leaves.airborne.size()<=6000&&e.halloween.airborne.size()<=6000&&e.halloween.webs.size()<=24,"population cap");
 Check(e.leaves.SettledCount()<=18000&&e.halloween.SettledCount()<=18000,"settled cap");
 auto heights=[](const auto& surfaces){for(auto&s:surfaces)for(float h:s.h)Check(std::isfinite(h)&&h>=0,"invalid surface");};heights(e.snow.surfaces);heights(e.rain.surfaces);heights(e.leaves.surfaces);heights(e.halloween.surfaces);
}
int main(){int pass=0,fail=0;auto test=[&](const std::string& title,std::function<void()> fn){ResetAllProfiles();RngState()=1234567;try{fn();++pass;std::printf("PASS %s\n",title.c_str());}catch(const std::exception&e){++fail;std::printf("FAIL %s: %s\n",title.c_str(),e.what());}};
 for(int from=0;from<4;++from)for(int to=0;to<4;++to)test(std::string("switch ")+ProfileName(from)+" -> "+ProfileName(to),[=]{auto w=Desktop();SuiteCfg().effect=from;Effects e;e.Sync(w);Step(e,w,60);auto before=e.Times();auto actors=Actors(e,from);bool changed=e.Select(to,w);Check(changed==(from!=to)&&e.Active()==to&&SuiteCfg().effect==to,"selection mismatch");Check(Actors(e,from)==actors,"switch erased previous CPU state");Step(e,w,1);auto after=e.Times();for(int k=0;k<4;++k)Check(k==to?after[k]>before[k]:after[k]==before[k],"inactive engine advanced");});
 for(int id=0;id<4;++id){
  auto label=std::string(ProfileName(id));
  test(label+" returns to its preserved scene",[=]{auto w=Desktop();SuiteCfg().effect=id;Effects e;e.Sync(w);Step(e,w,60);auto actors=Actors(e,id);auto time=e.Times()[id];e.Select((id+1)%4,w);Step(e,w,120);e.Select(id,w);Check(Actors(e,id)==actors&&e.Times()[id]==time,"return changed paused scene");});
  test(label+" disabled profile does no simulation work",[=]{auto w=Desktop();SuiteCfg().effect=id;SetField(id,L"enabled",0);Effects e;e.Sync(w);Step(e,w,120);Check(e.UpdateCounts()[id]==0&&Actors(e,id)==0,"disabled effect advanced");});
  test(label+" respects fullscreen pause",[=]{auto w=Desktop();w.gameOrFullscreen=true;SuiteCfg().effect=id;Effects e;e.Sync(w);Step(e,w,60);Check(e.UpdateCounts()[id]==0,"fullscreen did not pause");SetField(id,L"pauseFullscreen",0);Step(e,w,1);Check(e.UpdateCounts()[id]==1,"pause opt-out ignored");});
  test(label+" clear action affects only its own scene",[=]{auto w=Desktop();Effects e;for(int k=0;k<4;++k){e.Select(k,w);e.Sync(w);Step(e,w,60);}e.Select(id,w);size_t before[4];for(int k=0;k<4;++k)before[k]=Actors(e,k);e.ClearAll();Check(Actors(e,id)==0,"active scene not cleared");for(int k=0;k<4;++k)if(k!=id)Check(Actors(e,k)==before[k],"clear touched inactive scene");});
  test(label+" serializes every field independently",[=]{auto fields=ProfileFields(id);for(auto f:fields){int value=f.b?0:(f.hi+f.lo)/2;if(std::wstring(f.key)==L"lang")value=4;if(f.i)*f.i=value;else *f.b=false;}SetLanguage(4);auto encoded=EncodeSettings();auto expected=encoded;ResetAllProfiles();DecodeSettings(encoded);Check(EncodeSettings()==expected,"configuration round trip lost a field");});
  test(label+" clamp bounds reject invalid saved values",[=]{std::string input="["+std::string(ProfileName(id))+"]\n";for(auto f:ProfileFields(id)){std::wstring key(f.key);input+=std::string(key.begin(),key.end())+"=2147483647\n";}DecodeSettings(input);for(auto f:ProfileFields(id))if(std::wstring(f.key)!=L"lang")Check((f.i?*f.i:(int)*f.b)==f.hi,"upper bound not enforced");});
  test(label+" keeps its own density and frame-rate settings",[=]{SetField(id,L"intensity",17+id);SetField(id,L"fps",35+id);auto w=Desktop();Effects e;for(int k=0;k<4;++k){e.Select(k,w);if(k==id)Check(ActiveSettings().intensity==17+id&&ActiveSettings().fps==35+id,"wrong profile selected");}Check(Field(id,L"intensity")==17+id,"another profile changed saved values");});
  test(label+" ignores zero, negative and non-finite frames",[=]{auto w=Desktop();SuiteCfg().effect=id;Effects e;e.Sync(w);for(float dt:{0.f,-1.f,std::numeric_limits<float>::infinity(),std::numeric_limits<float>::quiet_NaN()})e.Update(dt,w,{0,0},false);Check(e.UpdateCounts()[id]==0,"invalid frame advanced");e.Update(99,w,{0,0},false);Check(e.Times()[id]>.099f&&e.Times()[id]<.101f,"large frame not limited");});
 }
 test("invalid effect IDs keep the current scene",[]{auto w=Desktop();Effects e;Check(!e.Select(-1,w)&&!e.Select(4,w)&&!e.Select(100000,w)&&e.Active()==0,"invalid selection accepted");});
 test("constructor repairs an invalid selected profile",[]{SuiteCfg().effect=999;Effects e;Check(e.Active()==0&&SuiteCfg().effect==0,"invalid startup profile");});
 test("all five languages synchronize across every profile",[]{for(int lang=0;lang<5;++lang){SetLanguage(lang);Check(SuiteCfg().lang==lang&&snowfx::Cfg().lang==lang&&rainfx::Cfg().lang==lang&&leavesfx::Cfg().lang==lang&&halloweenfx::Cfg().lang==lang,"language diverged");if(lang==4)Check(EncodeSettings().find("[snow]\nenabled=")!=std::string::npos&&EncodeSettings().find("lang=3")==std::string::npos,"German downgraded during profile encoding");}});
 test("language limits and automatic-language choice survive saving",[]{SetLanguage(88);Check(SuiteCfg().lang==4,"language upper bound");SetLanguage(-1);auto encoded=EncodeSettings();DecodeSettings(encoded);Check(SuiteCfg().lang==-1&&halloweenfx::Cfg().lang==-1,"automatic language lost");});
 test("unknown INI keys and malformed numbers do not overwrite defaults",[]{DecodeSettings("[suite]\neffect=garbage\nlang=9x\n[rain]\nintensity=50junk\nfallSpeed=99999999999999999\nunknown=0\n");Check(SuiteCfg().effect==0&&SuiteCfg().lang==-1&&rainfx::Cfg().intensity==45&&rainfx::Cfg().fallSpeed==40,"malformed input applied");});
 test("INI comments, CRLF, whitespace and duplicate values are deterministic",[]{DecodeSettings("; hi\r\n [suite] \r\neffect = 2\r\nlang=4\r\n [leaves]\r\n intensity=10\r\n intensity=66\r\n");Check(SuiteCfg().effect==2&&leavesfx::Cfg().intensity==66&&SuiteCfg().lang==4,"INI whitespace parsing");});
 test("legacy standalone sections import without a suite header",[]{DecodeSettings("[snow]\nintensity=11\n[rain]\nlightning=1\n[leaves]\nleafType=0\n[halloween]\ncontentMode=1\n");Check(snowfx::Cfg().intensity==11&&rainfx::Cfg().lightning&&leavesfx::Cfg().leafType==0&&halloweenfx::Cfg().contentMode==1,"legacy import lost settings");});
 test("presets and profile defaults never modify other effects",[]{rainfx::Cfg().intensity=72;halloweenfx::Cfg().contentMode=1;leavesfx::Cfg().leafType=0;snowfx::ApplyPreset(snowfx::PRESET_BLIZZARD);Check(rainfx::Cfg().intensity==72&&halloweenfx::Cfg().contentMode==1&&leavesfx::Cfg().leafType==0,"preset leaked");rainfx::ResetSettings();Check(snowfx::Cfg().intensity==100&&halloweenfx::Cfg().contentMode==1,"reset leaked");});
 test("lightning works only while the rain effect is selected",[]{auto w=Desktop();rainfx::Cfg().lightning=true;Effects e;e.FlashNow(w);Check(e.rain.bolt.segments.empty(),"snow triggered rain");e.Select(EFFECT_RAIN,w);e.FlashNow(w);Check(!e.rain.bolt.segments.empty(),"rain bolt absent");auto age=e.rain.bolt.age;e.Select(EFFECT_LEAVES,w);Step(e,w,60);Check(e.rain.bolt.age==age,"inactive lightning advanced");});
 test("disabled lightning never flashes after switching back",[]{auto w=Desktop();Effects e;e.Select(EFFECT_RAIN,w);rainfx::Cfg().lightning=false;e.FlashNow(w);Check(e.rain.bolt.segments.empty(),"disabled bolt emitted");});
 test("spiders can be spawned only in the Halloween effect",[]{auto w=Desktop();Effects e;for(int k=0;k<3;++k){e.Select(k,w);Check(!e.SpawnSpider(w),"another effect created a spider");}e.Select(3,w);Check(e.SpawnSpider(w),"Halloween spawn failed");});
 test("thread cutting cannot affect a paused Halloween scene",[]{auto w=Desktop();Density(0);Effects e;e.Select(3,w);e.halloween.webs.push_back(Spider());Check(e.CanCutThreads(),"visible thread not interactive");e.Select(1,w);Check(!e.CanCutThreads()&&!e.CutWebAt({500,100},w)&&e.halloween.webs.size()==1,"other effect cut paused thread");e.Select(3,w);Check(e.CutWebAt({500,100},w)&&e.halloween.webs.empty(),"resumed thread cut failed");});
 test("fullscreen pauses manual spider and lightning actions",[]{auto w=Desktop();w.gameOrFullscreen=true;Effects e;e.Select(3,w);Check(!e.SpawnSpider(w),"paused spider action");e.Select(1,w);rainfx::Cfg().lightning=true;e.FlashNow(w);Check(e.rain.bolt.segments.empty(),"paused lightning action");});
 test("rapid switching preserves population bounds and advances one engine per frame",[]{auto w=Desktop();Density(100);halloweenfx::Cfg().spiderInterval=4;Effects e;e.Sync(w);for(int i=0;i<1200;++i){e.Select(i%4,w);e.Update(1.f/30,w,{400,600},true);if(i%100==0)Finite(e);}auto n=e.UpdateCounts();for(auto v:n)Check(v==300,"inactive engine performed work");Finite(e);});
 test("monitor and window changes while inactive are synchronized on return",[]{auto w=Desktop();w.wins.push_back({(HWND)1,{100,300,900,800},false,false});Effects e;e.Sync(w);Check(e.snow.surfaces.size()==2,"fixture window absent");e.Select(1,w);w.wins.clear();w.monitors.clear();w.virt={0,0,2560,1440};w.monitors.push_back({w.virt,{0,0,2560,1400},1400,1.5f});e.Select(0,w);Check(e.snow.surfaces.size()==1&&e.snow.surfaces[0].width==2560&&e.snow.surfaces[0].scale==1.5f,"stale monitor/window state");});
 test("zero density stays idle through repeated selections",[]{Density(0);auto w=Desktop();Effects e;for(int i=0;i<40;++i){e.Select(i%4,w);Step(e,w,10);Check(e.Idle(),"switch spawned zero-density actors");}});
 test("saved selected effect is restored on the next controller",[]{SuiteCfg().effect=3;halloweenfx::Cfg().contentMode=1;auto saved=EncodeSettings();ResetAllProfiles();DecodeSettings(saved);Effects e;Check(e.Active()==3&&halloweenfx::Cfg().contentMode==1,"selected profile not restored");});
 std::printf("\n%d passed, %d failed\n",pass,fail);return fail?1:0;
}
